//! Port of `crypto/hmac.spec.ts`.
//!
//! Substitution: the `[fast-check]` tests compare libauth with Node.js's
//! `createHmac` (a JavaScript-only reference). Here, each compares libauth
//! with the HMACs which `createHmac` produced (in Node.js) for 100 fixed
//! `(secret, message)` pairs generated by [`FixedInputs`] with the test's
//! length bounds (see `HMAC_SHA256_NODE_JS` and `HMAC_SHA512_NODE_JS`).

use libauth::{bin_to_hex, hex_to_bin, hmac_sha256, hmac_sha512, sha256, sha512};

/// The `vectors` macro.
fn vectors(secret: &str, message: &str, expected_sha256: &str, expected_sha512: &str) {
    assert_eq!(
        hmac_sha256(&hex_to_bin(secret), &hex_to_bin(message), Some(&sha256)),
        hex_to_bin(expected_sha256)
    );
    assert_eq!(
        hmac_sha512(&hex_to_bin(secret), &hex_to_bin(message), Some(&sha512)),
        hex_to_bin(expected_sha512)
    );
}

