/// A deterministic generator of fixed test inputs (SplitMix64), mirrored by
/// the Node.js script which computed the expected reference values.
struct FixedInputs {
    state: u64,
}

impl FixedInputs {
    fn new(seed: u64) -> Self {
        FixedInputs { state: seed }
    }

    fn next_u64(&mut self) -> u64 {
        self.state = self.state.wrapping_add(0x9e37_79b9_7f4a_7c15);
        let mut z = self.state;
        z = (z ^ (z >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
        z ^ (z >> 31)
    }

    /// `min_length..=max_length` bytes (the length is `min_length +
    /// next_u64() % (max_length - min_length + 1)`), each the low byte of
    /// `next_u64()`.
    fn bytes(&mut self, min_length: usize, max_length: usize) -> Vec<u8> {
        let length = min_length as u64 + self.next_u64() % (max_length as u64 - min_length as u64 + 1);
        (0..length).map(|_| (self.next_u64() & 0xff) as u8).collect()
    }
}

