#[test]
fn fast_check_crypto_hmac_sha256_is_equivalent_to_node_js_native_hmac_sha256() {
    let mut inputs = FixedInputs::new(1);
    for expected in HMAC_SHA256_NODE_JS {
        let secret = inputs.bytes(1, 100);
        let message = inputs.bytes(1, 100);
        assert_eq!(bin_to_hex(&hmac_sha256(&secret, &message, None)), expected);
    }
}

#[test]
fn fast_check_crypto_hmac_sha512_is_equivalent_to_node_js_native_hmac_sha512() {
    let mut inputs = FixedInputs::new(2);
    for expected in HMAC_SHA512_NODE_JS {
        let secret = inputs.bytes(0, 100);
        let message = inputs.bytes(0, 100);
        assert_eq!(bin_to_hex(&hmac_sha512(&secret, &message, None)), expected);
    }
}
